import { PROJECT_ID } from "src/core/project/project"
import useLazyLoadScript from "src/lib/useLazyLoadScript"
import { canEditProposalSignal } from "src/core/edit-access-state"
import { useIsImperial } from "src/lib/unitSettings"
import { in3DSketchSignal } from "src/integrations/wsm-tools/wsr/api/EditWSMElementTool"
import { exitCurrentTool } from "src/core/toolsState"
import { useTranslator } from "src/i18n"

export default function ProjectSettings() {
  const imperial = useIsImperial()
  const isLoaded = useLazyLoadScript("/web-components/forma-project-settings/project-settings.js", "building-systems")
  if (!isLoaded) {
    return null
  }
  return (
    <div style={{ position: "absolute", zIndex: 200000 }}>
      <forma-project-settings
        project-id={PROJECT_ID}
        has-edit-access={canEditProposalSignal.value}
        imperial-units={imperial}
        show-measurement-units={true}
      ></forma-project-settings>
    </div>
  )
}

export function SettingsButtonWithPosition() {
  const t = useTranslator()
  return (
    <div style={{ display: "inline-block", position: "fixed", left: "22px", bottom: "25px" }}>
      <weave-tooltip text={t(($) => $.tooltips.settings)} nub="left-center">
        <weave-icon-button
          onClick={(e: Event) => {
            // 3d sketch seems to crash if we edit
            // certain settings in project settings while it's running
            // Long term it'd be better to fix those issues,
            // but for now we can just exit the tool to avoid the issue.
            if (in3DSketchSignal.peek()) {
              exitCurrentTool()
            }

            window.dispatchEvent(new CustomEvent("openProjectSettings", { detail: { referrer: "Design mode" } }))
            e.stopPropagation()
          }}
        >
          <SettingsIcon />
        </weave-icon-button>
      </weave-tooltip>
    </div>
  )
}

